{"cmd": "cd /workspace/target && python3 - <<'EOF'
import pandas as pd, numpy as np
a=pd.read_csv('/tmp/prof.csv'); b=pd.read_csv('reference/feature_profile.csv')
m=a.merge(b,on='feature',suffixes=('_new','_ref'))
bad=[]
for c in ['count','nulls','mean','std','min','p25','p50','p75','max']:
    diff = ~np.isclose(m[c+'_new'], m[c+'_ref'], rtol=0, atol=1e-9)
    for f in m.loc[diff,'feature']: bad.append((f,c,m.loc[m.feature==f,c+'_new'].iloc[0],m.loc[m.feature==f,c+'_ref'].iloc[0]))
for x in bad: print(x)
print("OK" if not bad else "DIFFS: %d"%len(bad))
EOF"}
